/* =====================================================================
   WebXemPhim - SCRIPT DỮ LIỆU MẪU (SQL Server / SSMS)
   ---------------------------------------------------------------------
   - Mở file này trong SSMS rồi bấm Execute (F5). Không cần sửa gì.
   - Nếu chưa có database WebXemPhimDB, script sẽ tự tạo database + bảng
     (đúng theo migration của project, kèm __MigrationHistory nên sau đó
     vẫn chạy Update-Database bình thường).
   - Nếu database đã có bảng (do chạy web / Update-Database), script chỉ
     thêm dữ liệu mẫu.
   - Chạy lại nhiều lần không bị trùng dữ liệu.
   - Muốn XÓA SẠCH dữ liệu cũ rồi nạp lại từ đầu: đổi @XoaHetDuLieuCu = 1
     ở phần 3 bên dưới.
   - Ảnh bìa, avatar, video đều trỏ tới file có sẵn trong thư mục
     WebXemPhim/Upload của project.
   ===================================================================== */

SET NOCOUNT ON;
GO

/* ---------------------------------------------------------------------
   1) TẠO DATABASE NẾU CHƯA CÓ
   --------------------------------------------------------------------- */
IF DB_ID(N'WebXemPhimDB') IS NULL
BEGIN
    PRINT N'Chưa có database WebXemPhimDB -> tạo mới.';
    CREATE DATABASE [WebXemPhimDB];
END
GO

USE [WebXemPhimDB];
GO

/* ---------------------------------------------------------------------
   2) TẠO BẢNG NẾU CHƯA CÓ (giống migration InitialCreate của EF)
   --------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.Films', N'U') IS NULL
BEGIN
    PRINT N'Chưa có bảng -> tạo schema theo migration của project.';

    CREATE TABLE [dbo].[Films] (
        [FilmId] INT IDENTITY(1,1) NOT NULL,
        [Title] NVARCHAR(255) NOT NULL,
        [OriginalTitle] NVARCHAR(MAX) NULL,
        [Description] NVARCHAR(MAX) NULL,
        [ReleaseYear] INT NULL,
        [IsMovie] BIT NOT NULL,
        [IsCompleted] BIT NOT NULL,
        [EpsisodeCount] INT NULL,
        [ThumbnailUrl] NVARCHAR(MAX) NULL,
        [CreatedAt] DATETIME NOT NULL,
        [UpdateAt] DATETIME NULL,
        [ViewCount] INT NOT NULL,
        [AverageRating] FLOAT NOT NULL,
        CONSTRAINT [PK_dbo.Films] PRIMARY KEY ([FilmId])
    );

    CREATE TABLE [dbo].[Users] (
        [UserId] INT IDENTITY(1,1) NOT NULL,
        [Username] NVARCHAR(100) NOT NULL,
        [Nickname] NVARCHAR(MAX) NULL,
        [Password] NVARCHAR(MAX) NULL,
        [Email] NVARCHAR(MAX) NULL,
        [AboutMe] NVARCHAR(MAX) NULL,
        [Role] NVARCHAR(MAX) NULL,
        [CreatedAt] DATETIME NOT NULL,
        [Avatar] NVARCHAR(MAX) NULL,
        CONSTRAINT [PK_dbo.Users] PRIMARY KEY ([UserId])
    );

    CREATE TABLE [dbo].[Genres] (
        [GenreId] INT IDENTITY(1,1) NOT NULL,
        [GenreName] NVARCHAR(MAX) NULL,
        CONSTRAINT [PK_dbo.Genres] PRIMARY KEY ([GenreId])
    );

    CREATE TABLE [dbo].[Episodes] (
        [EpisodeId] INT IDENTITY(1,1) NOT NULL,
        [EpisodeNumber] INT NOT NULL,
        [Title] NVARCHAR(MAX) NULL,
        [VideoUrl] NVARCHAR(MAX) NULL,
        [PublishedAt] DATETIME NULL,
        [ViewCount] INT NOT NULL,
        [FilmId] INT NOT NULL,
        CONSTRAINT [PK_dbo.Episodes] PRIMARY KEY ([EpisodeId]),
        CONSTRAINT [FK_dbo.Episodes_dbo.Films_FilmId] FOREIGN KEY ([FilmId]) REFERENCES [dbo].[Films]([FilmId]) ON DELETE CASCADE
    );
    CREATE INDEX [IX_FilmId] ON [dbo].[Episodes]([FilmId]);

    CREATE TABLE [dbo].[Comments] (
        [CommentId] INT IDENTITY(1,1) NOT NULL,
        [UserId] INT NOT NULL,
        [FilmId] INT NULL,
        [EpisodeId] INT NULL,
        [Content] NVARCHAR(MAX) NOT NULL,
        [CreatedAt] DATETIME NOT NULL,
        CONSTRAINT [PK_dbo.Comments] PRIMARY KEY ([CommentId]),
        CONSTRAINT [FK_dbo.Comments_dbo.Episodes_EpisodeId] FOREIGN KEY ([EpisodeId]) REFERENCES [dbo].[Episodes]([EpisodeId]),
        CONSTRAINT [FK_dbo.Comments_dbo.Films_FilmId] FOREIGN KEY ([FilmId]) REFERENCES [dbo].[Films]([FilmId]),
        CONSTRAINT [FK_dbo.Comments_dbo.Users_UserId] FOREIGN KEY ([UserId]) REFERENCES [dbo].[Users]([UserId]) ON DELETE CASCADE
    );
    CREATE INDEX [IX_UserId] ON [dbo].[Comments]([UserId]);
    CREATE INDEX [IX_FilmId] ON [dbo].[Comments]([FilmId]);
    CREATE INDEX [IX_EpisodeId] ON [dbo].[Comments]([EpisodeId]);

    CREATE TABLE [dbo].[Favourites] (
        [FavouriteId] INT IDENTITY(1,1) NOT NULL,
        [UserId] INT NOT NULL,
        [FilmId] INT NOT NULL,
        [AddedAt] DATETIME NOT NULL,
        CONSTRAINT [PK_dbo.Favourites] PRIMARY KEY ([FavouriteId]),
        CONSTRAINT [FK_dbo.Favourites_dbo.Films_FilmId] FOREIGN KEY ([FilmId]) REFERENCES [dbo].[Films]([FilmId]) ON DELETE CASCADE,
        CONSTRAINT [FK_dbo.Favourites_dbo.Users_UserId] FOREIGN KEY ([UserId]) REFERENCES [dbo].[Users]([UserId]) ON DELETE CASCADE
    );
    CREATE INDEX [IX_UserId] ON [dbo].[Favourites]([UserId]);
    CREATE INDEX [IX_FilmId] ON [dbo].[Favourites]([FilmId]);

    CREATE TABLE [dbo].[WatchHistories] (
        [WatchHistoryId] INT IDENTITY(1,1) NOT NULL,
        [UserId] INT NOT NULL,
        [EpisodeId] INT NOT NULL,
        [WatchedAt] DATETIME NOT NULL,
        CONSTRAINT [PK_dbo.WatchHistories] PRIMARY KEY ([WatchHistoryId]),
        CONSTRAINT [FK_dbo.WatchHistories_dbo.Episodes_EpisodeId] FOREIGN KEY ([EpisodeId]) REFERENCES [dbo].[Episodes]([EpisodeId]) ON DELETE CASCADE,
        CONSTRAINT [FK_dbo.WatchHistories_dbo.Users_UserId] FOREIGN KEY ([UserId]) REFERENCES [dbo].[Users]([UserId]) ON DELETE CASCADE
    );
    CREATE INDEX [IX_UserId] ON [dbo].[WatchHistories]([UserId]);
    CREATE INDEX [IX_EpisodeId] ON [dbo].[WatchHistories]([EpisodeId]);

    CREATE TABLE [dbo].[Ratings] (
        [RatingId] INT IDENTITY(1,1) NOT NULL,
        [Value] INT NOT NULL,
        [CreatedAt] DATETIME NOT NULL,
        [FilmId] INT NOT NULL,
        [UserId] INT NOT NULL,
        CONSTRAINT [PK_dbo.Ratings] PRIMARY KEY ([RatingId]),
        CONSTRAINT [FK_dbo.Ratings_dbo.Users_UserId] FOREIGN KEY ([UserId]) REFERENCES [dbo].[Users]([UserId]) ON DELETE CASCADE,
        CONSTRAINT [FK_dbo.Ratings_dbo.Films_FilmId] FOREIGN KEY ([FilmId]) REFERENCES [dbo].[Films]([FilmId]) ON DELETE CASCADE
    );
    CREATE INDEX [IX_FilmId] ON [dbo].[Ratings]([FilmId]);
    CREATE INDEX [IX_UserId] ON [dbo].[Ratings]([UserId]);

    CREATE TABLE [dbo].[Schedules] (
        [ScheduleId] INT IDENTITY(1,1) NOT NULL,
        [DayOfWeek] INT NOT NULL,
        [Time] TIME(7) NULL,
        [NextEpisodeDate] DATETIME NULL,
        [CreatedAt] DATETIME NOT NULL,
        [FilmId] INT NOT NULL,
        CONSTRAINT [PK_dbo.Schedules] PRIMARY KEY ([ScheduleId]),
        CONSTRAINT [FK_dbo.Schedules_dbo.Films_FilmId] FOREIGN KEY ([FilmId]) REFERENCES [dbo].[Films]([FilmId]) ON DELETE CASCADE
    );
    CREATE INDEX [IX_FilmId] ON [dbo].[Schedules]([FilmId]);

    CREATE TABLE [dbo].[VideoSources] (
        [VideoSourceId] INT IDENTITY(1,1) NOT NULL,
        [SeverName] NVARCHAR(MAX) NULL,
        [Url] NVARCHAR(MAX) NULL,
        [Quality] INT NOT NULL,
        [IsActive] BIT NOT NULL,
        [EpisodeId] INT NOT NULL,
        CONSTRAINT [PK_dbo.VideoSources] PRIMARY KEY ([VideoSourceId]),
        CONSTRAINT [FK_dbo.VideoSources_dbo.Episodes_EpisodeId] FOREIGN KEY ([EpisodeId]) REFERENCES [dbo].[Episodes]([EpisodeId]) ON DELETE CASCADE
    );
    CREATE INDEX [IX_EpisodeId] ON [dbo].[VideoSources]([EpisodeId]);

    CREATE TABLE [dbo].[GenreFilms] (
        [Genre_GenreId] INT NOT NULL,
        [Film_FilmId] INT NOT NULL,
        CONSTRAINT [PK_dbo.GenreFilms] PRIMARY KEY ([Genre_GenreId], [Film_FilmId]),
        CONSTRAINT [FK_dbo.GenreFilms_dbo.Genres_Genre_GenreId] FOREIGN KEY ([Genre_GenreId]) REFERENCES [dbo].[Genres]([GenreId]) ON DELETE CASCADE,
        CONSTRAINT [FK_dbo.GenreFilms_dbo.Films_Film_FilmId] FOREIGN KEY ([Film_FilmId]) REFERENCES [dbo].[Films]([FilmId]) ON DELETE CASCADE
    );
    CREATE INDEX [IX_Genre_GenreId] ON [dbo].[GenreFilms]([Genre_GenreId]);
    CREATE INDEX [IX_Film_FilmId] ON [dbo].[GenreFilms]([Film_FilmId]);

    /* Ghi lịch sử migration để Entity Framework coi như đã chạy
       InitialCreate + AddAdmin (Model lấy từ file .resx của migration). */
    IF OBJECT_ID(N'dbo.__MigrationHistory', N'U') IS NULL
        CREATE TABLE [dbo].[__MigrationHistory] (
            [MigrationId] NVARCHAR(150) NOT NULL,
            [ContextKey] NVARCHAR(300) NOT NULL,
            [Model] VARBINARY(MAX) NOT NULL,
            [ProductVersion] NVARCHAR(32) NOT NULL,
            CONSTRAINT [PK_dbo.__MigrationHistory] PRIMARY KEY ([MigrationId], [ContextKey])
        );

    INSERT INTO [dbo].[__MigrationHistory] ([MigrationId], [ContextKey], [Model], [ProductVersion])
    VALUES
        (N'202511230928201_InitialCreate', N'WebXemPhim.Migrations.Configuration', , N'6.5.1'),
        (N'202511251226566_AddAdmin',      N'WebXemPhim.Migrations.Configuration', , N'6.5.1');
END
GO

/* ---------------------------------------------------------------------
   3) NẠP DỮ LIỆU MẪU
   --------------------------------------------------------------------- */
SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRANSACTION;

DECLARE @XoaHetDuLieuCu BIT = 0;   -- đổi thành 1 để xóa sạch dữ liệu cũ trước khi nạp
DECLARE @Now DATETIME = GETDATE();

IF @XoaHetDuLieuCu = 1
BEGIN
    PRINT N'Đang xóa toàn bộ dữ liệu cũ...';
    IF OBJECT_ID(N'dbo.VipTransactions', N'U') IS NOT NULL
        EXEC (N'DELETE FROM dbo.VipTransactions;');
    DELETE FROM dbo.WatchHistories;
    DELETE FROM dbo.Comments;
    DELETE FROM dbo.Ratings;
    DELETE FROM dbo.Favourites;
    DELETE FROM dbo.Schedules;
    DELETE FROM dbo.VideoSources;
    DELETE FROM dbo.Episodes;
    DELETE FROM dbo.GenreFilms;
    DELETE FROM dbo.Films;
    DELETE FROM dbo.Genres;
    DELETE FROM dbo.Users;
    DBCC CHECKIDENT ('dbo.Films', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.Episodes', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.Users', RESEED, 0) WITH NO_INFOMSGS;
    DBCC CHECKIDENT ('dbo.Genres', RESEED, 0) WITH NO_INFOMSGS;
END

/* ---------- 3.1 Thể loại ---------- */
INSERT INTO dbo.Genres (GenreName)
SELECT g.GenreName
FROM (VALUES
    (N'Hành động'), (N'Tiên hiệp'), (N'Huyền huyễn'), (N'Võ thuật'), (N'Phiêu lưu'),
    (N'Hài hước'), (N'Thần thoại'), (N'Khoa học viễn tưởng'), (N'Cổ trang'), (N'Hoạt hình 3D')
) AS g(GenreName)
WHERE NOT EXISTS (SELECT 1 FROM dbo.Genres x WHERE x.GenreName = g.GenreName);

/* ---------- 3.2 Người dùng (mật khẩu lưu dạng chữ thường như code đăng nhập hiện tại) ---------- */
INSERT INTO dbo.Users (Username, Nickname, Password, Email, AboutMe, Role, CreatedAt, Avatar)
SELECT u.Username, u.Nickname, u.Password, u.Email, u.AboutMe, u.Role, DATEADD(DAY, -u.DaysAgo, @Now), u.Avatar
FROM (VALUES
    (N'admin',      N'Quản trị viên',  N'123123', N'admin@webxemphim.local',     N'Tài khoản quản trị hệ thống.',          N'Admin', 60, NULL),
    (N'nguyenvana', N'Văn A',          N'123456', N'nguyenvana@example.com',     N'Fan cứng phim tiên hiệp.',              N'User',  45, N'/Upload/Avatar/a3317e0e-07c4-4e8b-87ff-08785197e04f.jpg'),
    (N'tranthib',   N'Bé B',           N'123456', N'tranthib@example.com',       N'Thích phim hoạt hình 3D.',              N'User',  40, N'/Upload/Avatar/fffdbd57-74fe-4b5e-bedf-0cf93ffd5b3d.jpg'),
    (N'levanc',     N'C Đẹp Trai',     N'123456', N'levanc@example.com',         N'Cày phim mỗi tối.',                     N'User',  30, N'/Upload/Avatar/xien-chet-ba-may-gio.jpg'),
    (N'phamthid',   N'Dee',            N'123456', N'phamthid@example.com',       N'Mê Na Tra.',                            N'User',  20, N'/Upload/Avatar/Hình Nền Discord.png'),
    (N'hoangvane',  N'Ét Ô Ét',        N'123456', N'hoangvane@example.com',      NULL,                                     N'User',  10, NULL),
    (N'vipuser',    N'Khách VIP',      N'123456', N'vipuser@example.com',        N'Tài khoản dùng để test chức năng VIP.', N'User',   5, NULL)
) AS u(Username, Nickname, Password, Email, AboutMe, Role, DaysAgo, Avatar)
WHERE NOT EXISTS (SELECT 1 FROM dbo.Users x WHERE x.Username = u.Username);

/* ---------- 3.3 Phim ---------- */
