    Code VARCHAR(10) PRIMARY KEY, Title NVARCHAR(255), OriginalTitle NVARCHAR(200), Description NVARCHAR(1000),
    ReleaseYear INT, IsMovie BIT, IsCompleted BIT, EpCount INT, Thumb NVARCHAR(300), DaysAgo INT, ViewCount INT);

