DECLARE @NewFilms TABLE (FilmId INT, Title NVARCHAR(255));

INSERT INTO dbo.Films (Title, OriginalTitle, Description, ReleaseYear, IsMovie, IsCompleted, EpsisodeCount,
                       ThumbnailUrl, CreatedAt, UpdateAt, ViewCount, AverageRating)
OUTPUT inserted.FilmId, inserted.Title INTO @NewFilms
SELECT f.Title, f.OriginalTitle, f.Description, f.ReleaseYear, f.IsMovie, f.IsCompleted, f.EpCount,
       f.Thumb, DATEADD(DAY, -f.DaysAgo, @Now), NULL, f.ViewCount, 0
FROM @Films f
WHERE NOT EXISTS (SELECT 1 FROM dbo.Films x WHERE x.Title = f.Title)
ORDER BY f.DaysAgo;

-- Bảng ánh xạ mã phim -> FilmId (IsNew = 1 nếu phim vừa được thêm ở lần chạy này)
DECLARE @Map TABLE (Code VARCHAR(10) PRIMARY KEY, FilmId INT, IsNew BIT);
INSERT INTO @Map (Code, FilmId, IsNew)
SELECT f.Code, x.FilmId, CASE WHEN n.FilmId IS NULL THEN 0 ELSE 1 END
FROM @Films f
CROSS APPLY (SELECT TOP 1 FilmId FROM dbo.Films WHERE Title = f.Title ORDER BY FilmId) x
LEFT JOIN @NewFilms n ON n.FilmId = x.FilmId;

