INSERT INTO dbo.Episodes (EpisodeNumber, Title, VideoUrl, PublishedAt, ViewCount, FilmId)
SELECT e.EpNo, e.Title, @V + e.VideoFile, DATEADD(HOUR, e.HoursFromNow, @Now), e.ViewCount, m.FilmId
FROM @Eps e
JOIN @Map m ON m.Code = e.Code
WHERE NOT EXISTS (SELECT 1 FROM dbo.Episodes x WHERE x.FilmId = m.FilmId AND x.EpisodeNumber = e.EpNo)
ORDER BY m.FilmId, e.EpNo;

-- Nguồn video (server chính 720p cho mọi tập mới có video; phim lẻ Tiên Nghịch có thêm server trailer)
INSERT INTO dbo.VideoSources (SeverName, Url, Quality, IsActive, EpisodeId)
SELECT N'Server chính', ep.VideoUrl, 720, 1, ep.EpisodeId
FROM dbo.Episodes ep
JOIN @Map m ON m.FilmId = ep.FilmId
WHERE ep.VideoUrl IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM dbo.VideoSources v WHERE v.EpisodeId = ep.EpisodeId);

INSERT INTO dbo.VideoSources (SeverName, Url, Quality, IsActive, EpisodeId)
SELECT N'Server trailer', @V + N'Vietsub_Trailer_2_Movie_Tien_Nghich_-_Than_Lam_Chi_Chien_-_YouTube (1).mp4', 480, 1, ep.EpisodeId
FROM dbo.Episodes ep
JOIN @Map m ON m.FilmId = ep.FilmId AND m.Code = 'TNM'
WHERE ep.EpisodeNumber = 1
  AND NOT EXISTS (SELECT 1 FROM dbo.VideoSources v WHERE v.EpisodeId = ep.EpisodeId AND v.SeverName = N'Server trailer');

/* ---------- 3.6 Lịch chiếu (DayOfWeek: 0 = Chủ nhật, 1 = Thứ 2, ..., 6 = Thứ 7) ---------- */
INSERT INTO dbo.Schedules (DayOfWeek, Time, NextEpisodeDate, CreatedAt, FilmId)
SELECT s.Dow, CAST(s.T AS TIME), DATEADD(DAY, s.NextInDays, CAST(CAST(@Now AS DATE) AS DATETIME)) + CAST(CAST(s.T AS TIME) AS DATETIME), @Now, m.FilmId
FROM (VALUES
  ('TN',   3, '10:00', 3),
  ('TPTK', 0, '11:00', 4),
  ('TGHM', 2, '10:00', 5),
  ('VDCK', 5, '20:00', 4),
  ('DPTK', 6, '11:00', 1),
  ('TT',   4, '19:30', 5),
  ('LKMVN',1, '18:00', 2),
  ('PNTT', 6, '11:00', 6),
  ('MTK',  0, '10:00', 6),
  ('KL',   5, '10:00', 3),
  ('SHASH',2, '12:00', 1),
  ('NTCT', 3, '20:00', 2),
  ('TMDTH',1, '19:00', 4),
  ('TDQL', 5, '10:00', 1),
  ('TMND', 0, '12:00', 6),
  ('VKVT', 4, '20:00', 4),
  ('TTTD', 6, '10:00', 10),
  ('PNTT2',6, '11:00', 2),
  ('GT',   2, '10:00', 7),
  ('TAVT', 4, '10:00', 9)
) AS s(Code, Dow, T, NextInDays)
JOIN @Map m ON m.Code = s.Code
WHERE NOT EXISTS (SELECT 1 FROM dbo.Schedules x WHERE x.FilmId = m.FilmId);

