  ('hoangvane','LVDL',3,N'Đoạn võ hồn thức tỉnh làm khá đẹp.',150),
  ('phamthid','TGHMM',1,N'Bản điện ảnh đánh nhau mãn nhãn.',60)
) AS c(Username, Code, EpNo, Content, HoursAgo)
JOIN @Map m ON m.Code = c.Code
JOIN dbo.Users u ON u.Username = c.Username
LEFT JOIN dbo.Episodes ep ON ep.FilmId = m.FilmId AND ep.EpisodeNumber = c.EpNo
WHERE (c.EpNo IS NULL OR ep.EpisodeId IS NOT NULL)
  AND NOT EXISTS (SELECT 1 FROM dbo.Comments x WHERE x.UserId = u.UserId AND x.Content = c.Content);

/* ---------- 3.10 Lịch sử xem ---------- */
INSERT INTO dbo.WatchHistories (UserId, EpisodeId, WatchedAt)
SELECT u.UserId, ep.EpisodeId, DATEADD(HOUR, -w.HoursAgo, @Now)
FROM (VALUES
  ('nguyenvana','TN',1,72),('nguyenvana','TN',2,48),('nguyenvana','DPTK',2,24),('nguyenvana','TGHM',3,10),
  ('tranthib','DLDL',1,120),('tranthib','PNTT',1,30),('tranthib','SHASH',1,8),
  ('levanc','TN',2,6),('levanc','TT',1,12),
  ('phamthid','NT1',1,200),('phamthid','NT2',1,50),
  ('hoangvane','TPTK',1,20),('hoangvane','LKMVN',1,15),
  ('vipuser','DPTK',2,3),('vipuser','TN',2,2),
  ('nguyenvana','PNTT2',1,30),('nguyenvana','PNTT2',2,6),
  ('tranthib','TMND',1,18),('levanc','VTCT',1,400),
  ('vipuser','TDQL',2,4),('phamthid','TGHMM',1,60)
) AS w(Username, Code, EpNo, HoursAgo)
JOIN @Map m ON m.Code = w.Code
JOIN dbo.Users u ON u.Username = w.Username
JOIN dbo.Episodes ep ON ep.FilmId = m.FilmId AND ep.EpisodeNumber = w.EpNo
WHERE NOT EXISTS (SELECT 1 FROM dbo.WatchHistories x WHERE x.UserId = u.UserId AND x.EpisodeId = ep.EpisodeId);

/* ---------- 3.11 Cập nhật điểm trung bình theo bảng Ratings ---------- */
UPDATE f
SET AverageRating = ISNULL(r.AvgVal, 0)
FROM dbo.Films f
JOIN @Map m ON m.FilmId = f.FilmId
OUTER APPLY (SELECT ROUND(AVG(CAST(Value AS FLOAT)), 1) AS AvgVal FROM dbo.Ratings WHERE FilmId = f.FilmId) r;

COMMIT TRANSACTION;
PRINT N'Đã nạp dữ liệu mẫu thành công.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    DECLARE @Err NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR(N'Lỗi khi nạp dữ liệu mẫu, đã hoàn tác: %s', 16, 1, @Err);
END CATCH
GO

/* ---------------------------------------------------------------------
   4) DỮ LIỆU VIP (chỉ chạy khi database đã có cột/bảng của chức năng VIP)
   - Users.Balance, Users.VipExpiresAt, bảng VipTransactions.
   - Nếu chưa có chức năng VIP thì phần này tự bỏ qua.
   --------------------------------------------------------------------- */
IF COL_LENGTH(N'dbo.Users', N'VipExpiresAt') IS NOT NULL AND COL_LENGTH(N'dbo.Users', N'Balance') IS NOT NULL
BEGIN
    EXEC sp_executesql N'
        UPDATE dbo.Users SET Balance = 50000, VipExpiresAt = DATEADD(DAY, 30, GETDATE()) WHERE Username = N''vipuser'';
        UPDATE dbo.Users SET Balance = 200000 WHERE Username = N''nguyenvana'' AND Balance = 0;
        UPDATE dbo.Users SET Balance = 0, VipExpiresAt = DATEADD(DAY, -3, GETDATE()) WHERE Username = N''levanc'';';
    PRINT N'Đã cập nhật số dư / hạn VIP cho user mẫu.';

    IF OBJECT_ID(N'dbo.VipTransactions', N'U') IS NOT NULL
    BEGIN
        EXEC sp_executesql N'
            INSERT INTO dbo.VipTransactions (UserId, Amount, Type, Description, CreatedAt)
            SELECT u.UserId, t.Amount, t.Type, t.Description, DATEADD(DAY, -t.DaysAgo, GETDATE())
            FROM (VALUES
                (N''vipuser'',    100000, N''TopUp'',  N''Nạp tiền vào tài khoản (dữ liệu mẫu)'', 2),
                (N''vipuser'',     50000, N''BuyVip'', N''Mua VIP 30 ngày (dữ liệu mẫu)'',          1),
                (N''nguyenvana'', 200000, N''TopUp'',  N''Nạp tiền vào tài khoản (dữ liệu mẫu)'', 3),
                (N''levanc'',      50000, N''TopUp'',  N''Nạp tiền vào tài khoản (dữ liệu mẫu)'', 40),
                (N''levanc'',      50000, N''BuyVip'', N''Mua VIP 30 ngày - đã hết hạn (dữ liệu mẫu)'', 33)
            ) AS t(Username, Amount, Type, Description, DaysAgo)
            JOIN dbo.Users u ON u.Username = t.Username
            WHERE NOT EXISTS (SELECT 1 FROM dbo.VipTransactions x WHERE x.UserId = u.UserId AND x.Description = t.Description);';
        PRINT N'Đã thêm lịch sử giao dịch VIP mẫu.';
    END
END
ELSE
    PRINT N'Chưa có chức năng VIP trong database -> bỏ qua phần dữ liệu VIP.';
GO

/* ---------------------------------------------------------------------
   5) KIỂM TRA NHANH
   --------------------------------------------------------------------- */
SELECT N'Films' AS Bang, COUNT(*) AS SoDong FROM dbo.Films
UNION ALL SELECT N'Episodes', COUNT(*) FROM dbo.Episodes
UNION ALL SELECT N'Genres', COUNT(*) FROM dbo.Genres
UNION ALL SELECT N'GenreFilms', COUNT(*) FROM dbo.GenreFilms
UNION ALL SELECT N'Users', COUNT(*) FROM dbo.Users
UNION ALL SELECT N'Comments', COUNT(*) FROM dbo.Comments
UNION ALL SELECT N'Ratings', COUNT(*) FROM dbo.Ratings
UNION ALL SELECT N'Favourites', COUNT(*) FROM dbo.Favourites
UNION ALL SELECT N'WatchHistories', COUNT(*) FROM dbo.WatchHistories
UNION ALL SELECT N'Schedules', COUNT(*) FROM dbo.Schedules
UNION ALL SELECT N'VideoSources', COUNT(*) FROM dbo.VideoSources;
GO
